using OfficeIMO.Drawing;
using OfficeIMO.Html;
using OfficeIMO.Html.Pdf;
using OfficeIMO.Pdf;
using System.Security.Cryptography;
using System.Text.Json;

// Scratch v2 public observer; only exact copied local font resources are resolvable.
string inputs = Path.GetFullPath(args[0]);
string output = Path.GetFullPath(args[1]);
string sourceHead = args[2];
if (args.Length != 3 && (args.Length != 5 || args[3] != "--fixtures"))
    throw new ArgumentException("Usage: PageMarginProbe <inputs> <fresh-output> <source-sha> [--fixtures <case-id,...>]");
string[] selectedFixtures = args.Length == 5
    ? args[4].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
    : Array.Empty<string>();
string[] inputFiles = Directory.GetFiles(inputs, "*.html").OrderBy(p => p, StringComparer.Ordinal).ToArray();
bool Matches(string path, string selector) => Path.GetFileNameWithoutExtension(path) == selector
    || Path.GetFileNameWithoutExtension(path) == selector + "-expanded";
if (args.Length == 5 && (selectedFixtures.Length == 0 || selectedFixtures.Any(selector => !inputFiles.Any(path => Matches(path, selector)))))
    throw new ArgumentException("Every --fixtures selector must match an existing case or exact variant name.");
if (selectedFixtures.Length > 0) inputFiles = inputFiles.Where(path => selectedFixtures.Any(selector => Matches(path, selector))).ToArray();
if (Directory.Exists(output)) throw new IOException("Fresh output required; preserve prior observations.");
Directory.CreateDirectory(output);
byte[] regular = File.ReadAllBytes(Path.Combine(inputs, "regular.ttf"));
byte[] bold = File.ReadAllBytes(Path.Combine(inputs, "bold.ttf"));
byte[] gap = File.ReadAllBytes(Path.Combine(inputs, "gap.ttf"));
var fontFiles = new Dictionary<string, (string Path, byte[] Bytes)>(StringComparer.Ordinal) {
    [new Uri(Path.Combine(inputs, "regular.ttf")).AbsoluteUri] = (Path.Combine(inputs, "regular.ttf"), regular),
    [new Uri(Path.Combine(inputs, "bold.ttf")).AbsoluteUri] = (Path.Combine(inputs, "bold.ttf"), bold),
    [new Uri(Path.Combine(inputs, "gap.ttf")).AbsoluteUri] = (Path.Combine(inputs, "gap.ttf"), gap)
};
var localFontPolicy = new HtmlUrlPolicy {
    DisallowFileUrls = false, AllowDataUrls = false, AllowMailtoUrls = false,
    AllowProtocolRelativeUrls = false, RestrictUrlSchemes = true
};
localFontPolicy.AllowedUrlSchemes.Clear();
localFontPolicy.AllowedUrlSchemes.Add(Uri.UriSchemeFile);
var rows = new List<object>();
foreach (string input in inputFiles) {
    string name = Path.GetFileNameWithoutExtension(input);
    Uri baseUri = new Uri(input);
    var document = HtmlConversionDocument.Parse(File.ReadAllText(input), new HtmlConversionDocumentOptions {
        BaseUri = baseUri, ResourceUrlPolicy = localFontPolicy
    });
    foreach (var profile in new[] { HtmlRenderIntentProfile.PrintPaged, HtmlRenderIntentProfile.ScreenMediaPaged }) {
        string directory = Path.Combine(output, name, profile.ToString());
        Directory.CreateDirectory(directory);
        var resourceRequests = new List<object>();
        string phase = "Png";
        HtmlRenderResourceResolver exactFontResolver = (request, cancellationToken) => {
            cancellationToken.ThrowIfCancellationRequested();
            bool accepted = request.Kind == HtmlResourceKind.Font && request.Uri.IsFile
                && fontFiles.TryGetValue(request.Uri.AbsoluteUri, out _);
            lock (resourceRequests) resourceRequests.Add(new {
                phase, uri = request.Uri.AbsoluteUri, kind = request.Kind.ToString(), accepted,
                file = accepted ? FileBinding(fontFiles[request.Uri.AbsoluteUri].Path) : null
            });
            return Task.FromResult<HtmlResolvedResource?>(accepted
                ? new HtmlResolvedResource(fontFiles[request.Uri.AbsoluteUri].Bytes, "font/ttf") : null);
        };
        var options = new HtmlToPdfOptions {
            ViewportWidth = 360, ViewportHeight = 480,
            PageSize = new OfficePageSize(360D / 96D, 480D / 96D),
            Margins = HtmlRenderMargins.All(0),
            DefaultFontFamily = "MetricWitness", AllowSystemFontFallback = false,
            BaseUri = baseUri, ResourceUrlPolicy = localFontPolicy, ResourceResolver = exactFontResolver,
            ResourcePolicy = new PdfResourcePolicy {
                AllowLocalFileAccess = true, AllowDataUris = false, AllowEmbeddedPackageResources = false,
                AllowSystemFontEmbedding = false, AllowDocumentFontEmbedding = false, AllowRemoteResourceResolution = false
            },
            UserAgentStyles = HtmlRenderUserAgentStyleMode.Browser,
            FontFamily = new PdfEmbeddedFontFamily("MetricWitness", regular, bold)
        };
        options.Fonts.Add("MetricWitness", regular);
        options.Fonts.Add("MetricWitness", bold, OfficeFontStyle.Bold);
        options.Fonts.Add("MetricGap", gap);
        var rendered = await HtmlRenderEngine.ExecuteAsync(document, HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Png, options));
        phase = "Pdf";
        byte[] pdf = (await document.RenderToPdfResultAsync(HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Pdf, options))).ToBytes();
        string pdfPath = Path.Combine(directory, "document.pdf");
        File.WriteAllBytes(pdfPath, pdf);
        var direct = rendered.ExportImages();
        var saved = PdfReadDocument.Open(pdf, new PdfLoadOptions { IncludeArtifactText = true });
        var replay = saved.ExportImages(OfficeImageExportFormat.Png, new PdfImageExportOptions { Scale = 96D / 72D });
        var images = new List<object>();
        bool ownEqual = direct.Count == replay.Count;
        for (int index = 0; index < direct.Count; index++) {
            string directPath = Path.Combine(directory, $"direct-{index + 1:D2}.png");
            File.WriteAllBytes(directPath, direct[index].Bytes);
            bool equal = index < replay.Count && direct[index].Bytes.SequenceEqual(replay[index].Bytes);
            ownEqual &= equal;
            string replayPath = Path.Combine(directory, $"pdf-replay-{index + 1:D2}.png");
            if (index < replay.Count) File.WriteAllBytes(replayPath, replay[index].Bytes);
            images.Add(new { page = index + 1, direct = FileBinding(directPath), replay = index < replay.Count ? FileBinding(replayPath) : null, encodedBytesEqual = equal });
        }
        rows.Add(new {
            fixture = name, profile = profile.ToString(), input = FileBinding(input),
            baseUri = baseUri.AbsoluteUri, resourceRequests,
            resourcePolicy = new { allowedSchemes = new[] { "file" }, exactFontFileCount = fontFiles.Count,
                localFileAccess = true, systemFonts = false, documentHostFonts = false, remote = false },
            pages = rendered.Document.Pages.Count, pdfPages = saved.Pages.Count,
            ownPngPdfReplayEqual = ownEqual, pdf = FileBinding(pdfPath), images,
            scene = rendered.Document.Pages.Select(page => new {
                page.PageNumber, page.Width, page.Height, page.Margins,
                text = Walk(page.Scene).OfType<HtmlRenderText>().Select(text => new {
                    text.Source, text.SemanticRole, text.Text, text.X, text.Y, text.Width, text.Height,
                    text.TextAdvanceWidth, text.TextPaintWidth, alignment = text.Alignment.ToString(),
                    text.LineHeight, fontFamily = text.Font.FamilyName, fontSize = text.Font.Size,
                    fontStyle = text.Font.Style.ToString(), text.Baseline, text.BaselineOffset
                }).ToArray(),
                drawingText = DrawingTextObservations(page.CreateDrawing(), "page", Array.Empty<object>()).ToArray()
            }).ToArray(),
            savedPdfSpans = saved.Pages.Select((page, index) => new {
                page = index + 1, spans = page.GetTextSpans().Select(span => new { span.Text, span.X, span.Y, span.Advance }).ToArray()
            }).ToArray(),
            diagnostics = rendered.Document.Diagnostics.Select(d => new { d.Code, d.Source, d.Severity, d.LossKind }).ToArray()
        });
    }
}
var runtime = AppDomain.CurrentDomain.GetAssemblies()
    .Where(a => !a.IsDynamic && (a.GetName().Name!.StartsWith("OfficeIMO.", StringComparison.Ordinal) || a.GetName().Name!.StartsWith("AngleSharp", StringComparison.Ordinal)))
    .Select(a => FileBinding(a.Location)).ToArray();
File.WriteAllText(Path.Combine(output, "summary.json"), JsonSerializer.Serialize(new {
    declaredSourceHead = sourceHead, publicApiOnly = true, ambientFontFallbackEnabled = false,
    selectedFixtures, selectedInputFiles = inputFiles.Select(FileBinding).ToArray(),
    resourceBoundary = "File BaseUri plus public async resolver accepting only the three exact copied font file URIs/snapshots. No remote, data or ambient font resources.",
    regular = FileBinding(Path.Combine(inputs, "regular.ttf")), bold = FileBinding(Path.Combine(inputs, "bold.ttf")),
    gap = FileBinding(Path.Combine(inputs, "gap.ttf")), runtime, rows,
    boundary = "Observation only: actual author line-height/native comparisons require ROOT adjudication. PDF artifact text included; spatial spans are geometry observations."
}, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine($"Captured {rows.Count} input/profile observations; failures remain visible in summary.json.");
static object FileBinding(string path) => new { path, bytes = new FileInfo(path).Length, sha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant() };
static IEnumerable<object> DrawingTextObservations(OfficeDrawing drawing, string path, IReadOnlyList<object> ancestors) {
    for (int index = 0; index < drawing.Elements.Count; index++) {
        var element = drawing.Elements[index];
        string itemPath = path + "/" + index;
        if (element is OfficeDrawingText text) {
            yield return new {
                path = itemPath, coordinateSpace = ancestors.Count == 0 ? "page" : "nested-group-local",
                ancestors, text.Text, text.X, text.Y, text.Width, text.Height,
                text.TextAdvanceWidth, alignment = text.Alignment.ToString(), text.LineHeight,
                fontFamily = text.Font.FamilyName, fontSize = text.Font.Size
            };
        } else if (element is OfficeDrawingGroup group) {
            object frame = new { kind = "clip-group", group.X, group.Y, group.ContentOffsetX, group.ContentOffsetY, group.FrameTransform };
            foreach (var child in DrawingTextObservations(group.Drawing, itemPath, ancestors.Concat(new[] { frame }).ToArray())) yield return child;
        } else if (element is OfficeDrawingEffectGroup effect) {
            object frame = new { kind = "effect-group", effect.Transform, effect.Opacity };
            foreach (var child in DrawingTextObservations(effect.Drawing, itemPath, ancestors.Concat(new[] { frame }).ToArray())) yield return child;
        }
    }
}
static IEnumerable<HtmlRenderVisual> Walk(IEnumerable<HtmlRenderVisual> source) {
    foreach (var item in source) {
        yield return item;
        IEnumerable<HtmlRenderVisual>? children = item switch {
            HtmlRenderClipGroup x => x.Visuals, HtmlRenderPathClipGroup x => x.Visuals,
            HtmlRenderSemanticGroup x => x.Visuals, HtmlRenderEffectGroup x => x.Visuals,
            HtmlRenderLogicalTextGroup x => x.Visuals, HtmlRenderLayoutRegion x => x.Visuals,
            HtmlRenderFormField x => x.Visuals, _ => null
        };
        if (children != null) foreach (var child in Walk(children)) yield return child;
    }
}

packageConsumer.source:
using OfficeIMO.Drawing;
using OfficeIMO.Html;
using OfficeIMO.Html.Pdf;
using OfficeIMO.Pdf;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text.Json;

// Scratch qualification adapter. Rendering, fonts and saved-PDF replay use public owners.
Require(args.Length == 3, "Usage: Consumer <inputs> <fresh-output> <bound-acceptance.json>");
string inputs = Path.GetFullPath(args[0]), output = Path.GetFullPath(args[1]);
using var acceptance = JsonDocument.Parse(File.ReadAllBytes(args[2]));
var contract = acceptance.RootElement;
Require(contract.GetProperty("schema").GetString() == "officeimo.html.page-margin-cqw-package-acceptance/v1"
    && contract.GetProperty("contractApproved").GetBoolean(), "ROOT must approve the final contract first");
string head = contract.GetProperty("sourceHead").GetString()!;
Require(head.Length == 40, "Exact source SHA required");
foreach (string key in new[] { "sourceSeal", "sourceWitness", "sourceWitnessNet8", "crossFrameworkEquivalence", "nativeApprovalEvidence", "visualApprovalEvidence" }) Verify(contract.GetProperty(key));
using var seal = JsonDocument.Parse(File.ReadAllBytes(contract.GetProperty("sourceSeal").GetProperty("path").GetString()!));
Require((seal.RootElement.TryGetProperty("head", out var sealedHead) ? sealedHead : seal.RootElement.GetProperty("headSha")).GetString() == head, "Source seal head differs");
var rootApproval = contract.GetProperty("rootApproval");
Require(rootApproval.GetProperty("sourceHead").GetString() == head && rootApproval.GetProperty("nativeAndVisualApproved").GetBoolean(), "Native/visual acceptance is pending");
#if NET8_0
const string sourceWitnessKey = "sourceWitnessNet8", sourceWitnessFramework = "net8.0";
#else
const string sourceWitnessKey = "sourceWitness", sourceWitnessFramework = "net10.0";
#endif
using var source = JsonDocument.Parse(File.ReadAllBytes(contract.GetProperty(sourceWitnessKey).GetProperty("path").GetString()!));
Require(source.RootElement.GetProperty("declaredSourceHead").GetString() == head, "Approved source witness head differs");
var sourceRows = source.RootElement.GetProperty("rows").EnumerateArray().ToArray();
var fixtures = contract.GetProperty("expectedInputs").EnumerateArray().ToArray();
Require(fixtures.Length == 34 && contract.GetProperty("expectedInputCount").GetInt32() == 34
    && sourceRows.Length == 68 && contract.GetProperty("expectedObservations").GetInt32() == 68, "All 34 inputs and 68 observations are required");
foreach (var fixture in fixtures) {
    Verify(fixture);
    Require(Path.GetDirectoryName(fixture.GetProperty("path").GetString()) == inputs, "Only the bound exact input directory is admitted");
}
foreach (var font in contract.GetProperty("fontAssets").EnumerateArray()) Verify(font);
Require(!Directory.Exists(output) && !File.Exists(output), "Fresh consumer output required");
Directory.CreateDirectory(output);
#if NATIVEAOT
Require(!RuntimeFeature.IsDynamicCodeSupported && RuntimeInformation.ProcessArchitecture == Architecture.Arm64
    && RuntimeInformation.IsOSPlatform(OSPlatform.OSX), "The executed NativeAOT lane must be native osx-arm64");
#endif
byte[] regular = File.ReadAllBytes(Path.Combine(inputs, "regular.ttf"));
byte[] bold = File.ReadAllBytes(Path.Combine(inputs, "bold.ttf"));
byte[] gap = File.ReadAllBytes(Path.Combine(inputs, "gap.ttf"));
var fonts = new Dictionary<string, byte[]>(StringComparer.Ordinal) {
    [new Uri(Path.Combine(inputs, "regular.ttf")).AbsoluteUri] = regular,
    [new Uri(Path.Combine(inputs, "bold.ttf")).AbsoluteUri] = bold,
    [new Uri(Path.Combine(inputs, "gap.ttf")).AbsoluteUri] = gap
};
var resourcePolicy = new HtmlUrlPolicy { DisallowFileUrls = false, AllowDataUrls = false,
    AllowMailtoUrls = false, AllowProtocolRelativeUrls = false, RestrictUrlSchemes = true };
resourcePolicy.AllowedUrlSchemes.Clear(); resourcePolicy.AllowedUrlSchemes.Add(Uri.UriSchemeFile);
using var resultStream = File.Create(Path.Combine(output, "result.json"));
using var json = new Utf8JsonWriter(resultStream, new() { Indented = true });
json.WriteStartObject(); json.WriteString("sourceHead", head); json.WriteString("acceptanceSha256", Hash(File.ReadAllBytes(args[2])));
json.WriteString("framework", RuntimeInformation.FrameworkDescription); json.WriteString("architecture", RuntimeInformation.ProcessArchitecture.ToString());
json.WriteString("sourceWitnessFramework", sourceWitnessFramework); json.WriteString("sourceWitnessSha256", contract.GetProperty(sourceWitnessKey).GetProperty("sha256").GetString());
json.WriteBoolean("dynamicCodeSupported", RuntimeFeature.IsDynamicCodeSupported);
json.WriteBoolean("qualificationOnly", true); json.WriteBoolean("nativeBrowserConformance", false);
json.WritePropertyName("executedBinary"); FileRecord(json, Environment.ProcessPath!);
json.WriteStartArray("rows"); int observed = 0;
foreach (var fixture in fixtures) {
    string input = fixture.GetProperty("path").GetString()!, name = Path.GetFileNameWithoutExtension(input);
    Uri baseUri = new Uri(input);
    var document = HtmlConversionDocument.Parse(File.ReadAllText(input), new HtmlConversionDocumentOptions { BaseUri = baseUri, ResourceUrlPolicy = resourcePolicy });
    foreach (var profile in new[] { HtmlRenderIntentProfile.PrintPaged, HtmlRenderIntentProfile.ScreenMediaPaged }) {
        var expected = sourceRows.Single(row => row.GetProperty("fixture").GetString() == name && row.GetProperty("profile").GetString() == profile.ToString());
        string directory = Path.Combine(output, name, profile.ToString()); Directory.CreateDirectory(directory);
        int acceptedResources = 0;
        var options = new HtmlToPdfOptions {
            ViewportWidth = 360, ViewportHeight = 480, PageSize = new OfficePageSize(360D / 96D, 480D / 96D),
            Margins = HtmlRenderMargins.All(0), DefaultFontFamily = "MetricWitness", AllowSystemFontFallback = false,
            BaseUri = baseUri, ResourceUrlPolicy = resourcePolicy,
            ResourceResolver = (request, token) => {
                token.ThrowIfCancellationRequested();
                Require(request.Kind == HtmlResourceKind.Font && request.Uri.IsFile && fonts.ContainsKey(request.Uri.AbsoluteUri), "Unexpected resource request");
                Interlocked.Increment(ref acceptedResources);
                return Task.FromResult<HtmlResolvedResource?>(new HtmlResolvedResource(fonts[request.Uri.AbsoluteUri], "font/ttf"));
            },
            ResourcePolicy = new PdfResourcePolicy { AllowLocalFileAccess = true, AllowDataUris = false,
                AllowEmbeddedPackageResources = false, AllowSystemFontEmbedding = false,
                AllowDocumentFontEmbedding = false, AllowRemoteResourceResolution = false },
            UserAgentStyles = HtmlRenderUserAgentStyleMode.Browser,
            FontFamily = new PdfEmbeddedFontFamily("MetricWitness", regular, bold)
        };
        options.Fonts.Add("MetricWitness", regular); options.Fonts.Add("MetricWitness", bold, OfficeFontStyle.Bold); options.Fonts.Add("MetricGap", gap);
        var rendered = await HtmlRenderEngine.ExecuteAsync(document, HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Png, options));
        var pdfResult = await document.RenderToPdfResultAsync(HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Pdf, options));
        var expectedDiagnostics = contract.GetProperty("expectedDiagnosticsByFixture").GetProperty(name);
        VerifyDiagnostics(rendered.Document.Diagnostics, expected.GetProperty("diagnostics"), expectedDiagnostics);
        VerifyDiagnostics(pdfResult.RenderResult.Document.Diagnostics, expected.GetProperty("diagnostics"), expectedDiagnostics);
        bool authoredClippingControl = name == "17-px81_6";
        Require(rendered.Document.HasLoss == authoredClippingControl && pdfResult.RenderResult.Document.HasLoss == authoredClippingControl,
            "Only the exact authored physical clipping control may report loss");
        Require(acceptedResources > 0, "The exact local font route must execute");
        Require(!rendered.Document.Diagnostics.Concat(pdfResult.RenderResult.Document.Diagnostics).Any(d => d.Code.Contains("Font", StringComparison.OrdinalIgnoreCase)
            && d.Severity is HtmlDiagnosticSeverity.Warning or HtmlDiagnosticSeverity.Error), "Font warnings/errors are not accepted");
        string pdfPath = Path.Combine(directory, "document.pdf"); File.WriteAllBytes(pdfPath, pdfResult.ToBytes());
        var saved = PdfReadDocument.Open(File.ReadAllBytes(pdfPath), new PdfLoadOptions { IncludeArtifactText = true });
        var direct = rendered.ExportImages(); var replay = saved.ExportImages(OfficeImageExportFormat.Png, new PdfImageExportOptions { Scale = 96D / 72D });
        int pages = contract.GetProperty("expectedPages").GetInt32();
        Require(pages == 1 && expected.GetProperty("pages").GetInt32() == pages && expected.GetProperty("pdfPages").GetInt32() == pages
            && rendered.Document.Pages.Count == pages && saved.Pages.Count == pages && direct.Count == pages && replay.Count == pages,
            "Exactly one complete actual page per current fixture required");
        json.WriteStartObject(); json.WriteString("fixture", name); json.WriteString("profile", profile.ToString()); json.WriteNumber("pages", pages);
        json.WriteNumber("acceptedFontResourceRequests", acceptedResources); json.WriteBoolean("ownPngPdfReplayEqual", true); json.WriteBoolean("approvedSourcePngEqual", true);
        json.WriteBoolean("authoredClippingControl", authoredClippingControl);
        json.WriteBoolean("pngHasLoss", rendered.Document.HasLoss); json.WriteBoolean("pdfHasLoss", pdfResult.RenderResult.Document.HasLoss);
        json.WritePropertyName("pngDiagnostics"); WriteDiagnostics(json, rendered.Document.Diagnostics);
        json.WritePropertyName("pdfDiagnostics"); WriteDiagnostics(json, pdfResult.RenderResult.Document.Diagnostics);
        json.WritePropertyName("input"); FileRecord(json, input); json.WritePropertyName("pdf"); FileRecord(json, pdfPath);
        json.WriteStartArray("pagesEvidence");
        for (int index = 0; index < pages; index++) {
            var page = rendered.Document.Pages[index]; var sourcePage = expected.GetProperty("scene")[index];
            var paper = contract.GetProperty("paperCssPxByFixture").GetProperty(name);
            Require(Near(page.Width, paper[0].GetDouble()) && Near(page.Height, paper[1].GetDouble())
                && Near(page.Width, sourcePage.GetProperty("Width").GetDouble()) && Near(page.Height, sourcePage.GetProperty("Height").GetDouble()), "CSS paper geometry differs");
            Require(direct[index].Bytes.SequenceEqual(replay[index].Bytes), "Every own PNG must equal the actual saved-PDF replay");
            var sourceImage = expected.GetProperty("images")[index].GetProperty("direct"); Verify(sourceImage);
            Require(Hash(direct[index].Bytes) == sourceImage.GetProperty("sha256").GetString(), "Package pixels differ from the framework-matched actual source");
            string directPath = Path.Combine(directory, $"direct-{index + 1:D2}.png"), replayPath = Path.Combine(directory, $"pdf-replay-{index + 1:D2}.png");
            File.WriteAllBytes(directPath, direct[index].Bytes); File.WriteAllBytes(replayPath, replay[index].Bytes);
            var texts = Walk(page.Scene).OfType<HtmlRenderText>().ToArray();
            var expectedTexts = sourcePage.GetProperty("text").EnumerateArray().ToArray();
            Require(texts.Length == expectedTexts.Length, "Complete scene text inventory differs from source");
            Require(Compact(string.Concat(texts.Select(t => t.Text))).Contains(Compact(contract.GetProperty("requiredBodyText").GetString()!), StringComparison.Ordinal)
                && Compact(string.Concat(texts.Select(t => t.Text))).Contains(Compact(contract.GetProperty("requiredMarginTextByFixture").GetProperty(name).GetString()!), StringComparison.Ordinal), "Body or margin text is missing");
            json.WriteStartObject(); json.WriteNumber("page", index + 1); json.WriteNumber("width", page.Width); json.WriteNumber("height", page.Height);
            json.WritePropertyName("direct"); FileRecord(json, directPath); json.WritePropertyName("replay"); FileRecord(json, replayPath);
            json.WriteStartArray("sceneText");
            for (int item = 0; item < texts.Length; item++) {
                var t = texts[item]; var e = expectedTexts[item];
                Require(e.GetProperty("Text").GetString() == t.Text && e.GetProperty("Source").GetString() == t.Source
                    && e.GetProperty("SemanticRole").GetString() == t.SemanticRole && Near(e.GetProperty("X").GetDouble(), t.X)
                    && Near(e.GetProperty("Y").GetDouble(), t.Y) && Near(e.GetProperty("Width").GetDouble(), t.Width)
                    && Near(e.GetProperty("Height").GetDouble(), t.Height) && Near(e.GetProperty("LineHeight").GetDouble(), t.LineHeight)
                    && NullableNear(e.GetProperty("TextAdvanceWidth"), t.TextAdvanceWidth) && NullableNear(e.GetProperty("TextPaintWidth"), t.TextPaintWidth)
                    && e.GetProperty("alignment").GetString() == t.Alignment.ToString() && e.GetProperty("fontFamily").GetString() == t.Font.FamilyName
                    && Near(e.GetProperty("fontSize").GetDouble(), t.Font.Size) && e.GetProperty("fontStyle").GetString() == t.Font.Style.ToString()
                    && e.GetProperty("Baseline").GetInt32() == (int)t.Baseline && Near(e.GetProperty("BaselineOffset").GetDouble(), t.BaselineOffset),
                    "Scene content/typography/geometry differs from approved source");
                json.WriteStartObject(); json.WriteString("text", t.Text); json.WriteString("source", t.Source); json.WriteNumber("x", t.X); json.WriteNumber("y", t.Y);
                json.WriteNumber("width", t.Width); json.WriteNumber("height", t.Height); json.WriteNumber("lineHeight", t.LineHeight);
                json.WriteString("fontFamily", t.Font.FamilyName); json.WriteNumber("fontSize", t.Font.Size); json.WriteEndObject();
            }
            json.WriteEndArray();
            var drawing = DrawingText(page.CreateDrawing(), "page").ToArray();
            var expectedDrawing = sourcePage.GetProperty("drawingText").EnumerateArray().ToArray();
            Require(drawing.Length == expectedDrawing.Length, "Public drawing text inventory differs");
            json.WriteStartArray("drawingText");
            for (int item = 0; item < drawing.Length; item++) {
                var a = drawing[item]; var e = expectedDrawing[item]; var t = a.Text;
                Require(e.GetProperty("path").GetString() == a.Path && e.GetProperty("Text").GetString() == t.Text
                    && Near(e.GetProperty("X").GetDouble(), t.X) && Near(e.GetProperty("Y").GetDouble(), t.Y)
                    && Near(e.GetProperty("Width").GetDouble(), t.Width) && Near(e.GetProperty("Height").GetDouble(), t.Height)
                    && NullableNear(e.GetProperty("TextAdvanceWidth"), t.TextAdvanceWidth) && e.GetProperty("alignment").GetString() == t.Alignment.ToString()
                    && NullableNear(e.GetProperty("LineHeight"), t.LineHeight) && e.GetProperty("fontFamily").GetString() == t.Font.FamilyName
                    && Near(e.GetProperty("fontSize").GetDouble(), t.Font.Size), "Public drawing typography/geometry differs");
                json.WriteStartObject(); json.WriteString("path", a.Path); json.WriteString("text", t.Text); json.WriteNumber("x", t.X); json.WriteNumber("y", t.Y);
                json.WriteNumber("width", t.Width); json.WriteNumber("height", t.Height);
                if (t.LineHeight.HasValue) json.WriteNumber("lineHeight", t.LineHeight.Value); else json.WriteNull("lineHeight");
                json.WriteEndObject();
            }
            json.WriteEndArray();
            var spans = saved.Pages[index].GetTextSpans().ToArray();
            var expectedSpans = expected.GetProperty("savedPdfSpans")[index].GetProperty("spans").EnumerateArray().ToArray();
            Require(spans.Length == expectedSpans.Length, "Saved PDF text inventory differs");
            json.WriteStartArray("savedPdfSpans");
            for (int item = 0; item < spans.Length; item++) {
                var a = spans[item]; var e = expectedSpans[item];
                Require(e.GetProperty("Text").GetString() == a.Text && Near(e.GetProperty("X").GetDouble(), a.X)
                    && Near(e.GetProperty("Y").GetDouble(), a.Y) && Near(e.GetProperty("Advance").GetDouble(), a.Advance), "Saved PDF content/position/advance differs");
                json.WriteStartObject(); json.WriteString("text", a.Text); json.WriteNumber("x", a.X); json.WriteNumber("y", a.Y); json.WriteNumber("advance", a.Advance); json.WriteEndObject();
            }
            json.WriteEndArray(); json.WriteBoolean("completeSceneDrawingAndSavedTextEqual", true); json.WriteEndObject();
        }
        json.WriteEndArray(); json.WriteEndObject(); json.Flush(); observed++;
    }
}
Require(observed == 68, "All 68 current observations must execute");
json.WriteEndArray(); json.WriteStartArray("runtime");
#if !NATIVEAOT
foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies().Where(a => !a.IsDynamic
    && (a.GetName().Name!.StartsWith("OfficeIMO.", StringComparison.Ordinal) || a.GetName().Name!.StartsWith("AngleSharp", StringComparison.Ordinal)))) FileRecord(json, assembly.Location);
#endif
json.WriteEndArray(); json.WriteNumber("observations", observed); json.WriteBoolean("passed", true); json.WriteEndObject(); json.Flush();
Console.WriteLine("All 68 packed public observations passed: exact local fonts, approved framework-matched pixels/scene/drawing/saved text and own PNG/PDF replay.");

static void Require(bool value, string message) { if (!value) throw new InvalidDataException(message); }
static bool Near(double a, double b) => Math.Abs(a - b) <= .001D;
static bool NullableNear(JsonElement e, double? a) => e.ValueKind == JsonValueKind.Null ? a == null : a.HasValue && Near(e.GetDouble(), a.Value);
static string Hash(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
static string Compact(string value) => string.Concat(value.Where(c => !char.IsWhiteSpace(c)));
static void VerifyDiagnostics(IEnumerable<HtmlDiagnostic> diagnostics, JsonElement source, JsonElement allowed) {
    var actual = diagnostics.ToArray(); var witnessed = source.EnumerateArray().ToArray(); var admitted = allowed.EnumerateArray().ToArray();
    Require(actual.Length == witnessed.Length && actual.Length == admitted.Length, "Exact source/approved diagnostic inventory required for both encoder phases");
    for (int index = 0; index < actual.Length; index++) {
        var a = actual[index];
        foreach (var e in new[] { witnessed[index], admitted[index] })
            Require(e.GetProperty("Code").GetString() == a.Code && e.GetProperty("Source").GetString() == a.Source
                && e.GetProperty("Severity").GetInt32() == (int)a.Severity && e.GetProperty("LossKind").GetInt32() == (int)a.LossKind,
                "Unexpected, missing or changed typed diagnostic");
    }
}
static void WriteDiagnostics(Utf8JsonWriter writer, IEnumerable<HtmlDiagnostic> diagnostics) {
    writer.WriteStartArray();
    foreach (var diagnostic in diagnostics) {
        writer.WriteStartObject(); writer.WriteString("Code", diagnostic.Code); writer.WriteString("Source", diagnostic.Source);
        writer.WriteNumber("Severity", (int)diagnostic.Severity); writer.WriteNumber("LossKind", (int)diagnostic.LossKind); writer.WriteEndObject();
    }
    writer.WriteEndArray();
}
static void Verify(JsonElement binding) {
    string path = binding.GetProperty("path").GetString()!; byte[] bytes = File.ReadAllBytes(path);
    Require(bytes.LongLength == binding.GetProperty("bytes").GetInt64() && Hash(bytes) == binding.GetProperty("sha256").GetString(), "Bound input/evidence changed: " + path);
}
static void FileRecord(Utf8JsonWriter writer, string path) {
    byte[] bytes = File.ReadAllBytes(path); writer.WriteStartObject(); writer.WriteString("path", path); writer.WriteNumber("bytes", bytes.LongLength); writer.WriteString("sha256", Hash(bytes)); writer.WriteEndObject();
}
static IEnumerable<(string Path, OfficeDrawingText Text)> DrawingText(OfficeDrawing drawing, string path) {
    for (int index = 0; index < drawing.Elements.Count; index++) {
        string childPath = path + "/" + index; var element = drawing.Elements[index];
        if (element is OfficeDrawingText text) yield return (childPath, text);
        else if (element is OfficeDrawingGroup group) { foreach (var child in DrawingText(group.Drawing, childPath)) yield return child; }
        else if (element is OfficeDrawingEffectGroup effect) { foreach (var child in DrawingText(effect.Drawing, childPath)) yield return child; }
    }
}
static IEnumerable<HtmlRenderVisual> Walk(IEnumerable<HtmlRenderVisual> visuals) {
    foreach (var visual in visuals) {
        yield return visual;
        IEnumerable<HtmlRenderVisual>? children = visual switch {
            HtmlRenderClipGroup x => x.Visuals, HtmlRenderPathClipGroup x => x.Visuals, HtmlRenderSemanticGroup x => x.Visuals,
            HtmlRenderEffectGroup x => x.Visuals, HtmlRenderLogicalTextGroup x => x.Visuals, HtmlRenderLayoutRegion x => x.Visuals,
            HtmlRenderFormField x => x.Visuals, _ => null
        };
        if (children != null) foreach (var child in Walk(children)) yield return child;
    }
}
